"""
tournament.py
--------------
A Python module to schedule and manage tournaments.
Supports round-robin and single-elimination formats, standings with tie-breakers, and schedule printing.
"""
import itertools
from typing import List, Dict, Optional, Tuple, Any
import random
import json

class Team:
    """Class representing a team"""
    def __init__(self, name: str):
        self.name = name

class Venue:
    """Class representing a venue"""
    def __init__(self, name: str):
        self.name = name

class TimeSlot:
    """Class representing a time slot"""
    def __init__(self, label: str):
        self.label = label

class Match:
    """Class representing a match between teams"""
    def __init__(self, team1: Team, team2: Team, venue: Venue, time: TimeSlot):
        self.team1 = team1
        self.team2 = team2
        self.venue = venue
        self.time = time
        self.score = None # (score1, score2)

    def set_result(self, score1: int, score2: int):
        self.score = (score1, score2)

class RoundRobinScheduler:
    """Schedules a round-robin tournament"""
    def __init__(self, teams: List[Team], venues: List[Venue], slots: List[TimeSlot]):
        self.teams = teams
        self.venues = venues
        self.slots = slots
        self.matches = self.schedule_matches()

    def schedule_matches(self) -> List[Match]:
        matches = []
        n = len(self.teams)
        teams = self.teams[:]
        if n % 2:
            teams.append(Team("BYE"))
            n += 1
        rounds = n - 1
        matches_per_round = n // 2
        for rnd in range(rounds):
            round_matches = []
            for i in range(matches_per_round):
                t1 = teams[i]
                t2 = teams[n-1-i]
                if t1.name != "BYE" and t2.name != "BYE":
                    venue = self.venues[(rnd * matches_per_round + i) % len(self.venues)]
                    slot = self.slots[(rnd * matches_per_round + i) % len(self.slots)]
                    match = Match(t1, t2, venue, slot)
                    round_matches.append(match)
            teams.insert(1, teams.pop())
            matches.extend(round_matches)
        return matches

    def print_schedule(self):
        for match in self.matches:
            print(f"{match.team1.name} vs {match.team2.name} at {match.venue.name} on {match.time.label}")

class SingleEliminationScheduler:
    """Schedules a single-elimination tournament"""
    def __init__(self, teams: List[Team], venues: List[Venue], slots: List[TimeSlot]):
        self.teams = teams
        self.venues = venues
        self.slots = slots
        self.matches = self.schedule_matches()

    def schedule_matches(self) -> List[Match]:
        matches = []
        n = len(self.teams)
        bracket = self.teams[:]
        if not (n & (n-1) == 0):
            # Next power of two
            pad = 1<<(n-1).bit_length()
            while len(bracket) < pad:
                bracket.append(Team("BYE"))
            n = pad
        round_num = 0
        round_teams = bracket
        while len(round_teams) > 1:
            next_round = []
            for i in range(0, len(round_teams), 2):
                t1 = round_teams[i]
                t2 = round_teams[i+1]
                if t1.name == "BYE":
                    next_round.append(t2)
                elif t2.name == "BYE":
                    next_round.append(t1)
                else:
                    venue = self.venues[(round_num*len(round_teams)//2 + i//2)%len(self.venues)]
                    slot = self.slots[(round_num*len(round_teams)//2 + i//2)%len(self.slots)]
                    match = Match(t1, t2, venue, slot)
                    matches.append(match)
                    next_round.append(random.choice([t1, t2])) # Placeholder for advancement
            round_num += 1
            round_teams = next_round
        return matches

    def print_schedule(self):
        for match in self.matches:
            print(f"{match.team1.name} vs {match.team2.name} at {match.venue.name} on {match.time.label}")

class Standings:
    """Manages standings, including tie-breakers."""
    def __init__(self, teams: List[Team]):
        self.records = {team.name: {"points": 0, "gf": 0, "ga": 0, "wins": 0, "draws": 0, "losses": 0} for team in teams}

    def record_result(self, t1: str, t2: str, s1: int, s2: int):
        rec1 = self.records[t1]
        rec2 = self.records[t2]
        rec1["gf"] += s1
        rec1["ga"] += s2
        rec2["gf"] += s2
        rec2["ga"] += s1
        if s1 > s2:
            rec1["points"] += 3
            rec1["wins"] += 1
            rec2["losses"] += 1
        elif s1 < s2:
            rec2["points"] += 3
            rec2["wins"] += 1
            rec1["losses"] += 1
        else:
            rec1["points"] += 1
            rec2["points"] += 1
            rec1["draws"] += 1
            rec2["draws"] += 1

    def sorted_standings(self, tie_breakers: List[str] = ["points","gf-g","wins"]):
        def cmp_key(item):
            rec = item[1]
            key = [rec["points"]]
            for tieb in tie_breakers[1:]:
                if tieb == "gf-g":
                    key.append(rec["gf"] - rec["ga"])
                else:
                    key.append(rec.get(tieb, 0))
            return tuple(key)
        return sorted(self.records.items(), key=cmp_key, reverse=True)

    def print_standings(self):
        standings = self.sorted_standings()
        print("Team | Pts | GF | GA | W | D | L")
        for team, rec in standings:
            print(f"{team} | {rec['points']} | {rec['gf']} | {rec['ga']} | {rec['wins']} | {rec['draws']} | {rec['losses']}")

class Tournament:
    """Central class to manage a tournament. Handles loading config, scheduling, results, standings."""
    def __init__(self, config_file: str):
        with open(config_file) as f:
            self.config = json.load(f)
        self.teams = [Team(name) for name in self.config["teams"]]
        self.venues = [Venue(name) for name in self.config["venues"]]
        self.times = [TimeSlot(label) for label in self.config["timeslots"]]
        self.mode = self.config["mode"]
        self.tie_breakers = self.config['scoring']['tie_breakers']
        self.standings = Standings(self.teams)
        if self.mode == "round-robin":
            self.scheduler = RoundRobinScheduler(self.teams, self.venues, self.times)
        else:
            self.scheduler = SingleEliminationScheduler(self.teams, self.venues, self.times)
        self.matches = self.scheduler.matches

    def print_schedule(self):
        self.scheduler.print_schedule()

    def simulate_results(self):
        for match in self.matches:
            score1 = random.randint(0, 5)
            score2 = random.randint(0, 5)
            match.set_result(score1, score2)
            self.standings.record_result(match.team1.name, match.team2.name, score1, score2)

    def print_standings(self):
        self.standings.print_standings()

def main():
    import argparse
    parser = argparse.ArgumentParser(description='Tournament Scheduler')
    parser.add_argument('config', help='Path to config.json')
    parser.add_argument('--standings', action='store_true', help='Print standings after simulation')
    args = parser.parse_args()
    t = Tournament(args.config)
    print('Schedule:')
    t.print_schedule()
    t.simulate_results()
    if args.standings:
        print('\nStandings:')
        t.print_standings()

if __name__ == '__main__':
    main()
